/*!
 * Two Squares — Work index (work.html)
 *
 * State lives on <html>: data-work-filter / data-work-view. The inline <head> script
 * (generated by tools/build_work.py) sets both before first paint from ?filter= and
 * localStorage, and CSS does all the showing and hiding. This file keeps the controls,
 * the URL, the title and the empty state in sync, and animates every change:
 *   filter → GSAP Flip (leaving items fade/scale out, the rest glide, the page below glides)
 *            + a masked line roll on the headline / intro / CTA / count
 *   view   → Rows ⇄ Grid: names and meta glide (Flip), each project's lead image morphs
 *            into the other layout's lead (transform + clip-path, no distortion)
 *   grid   → fine pointers: the cover crossfades to the project's loop on hover
 * Without GSAP (or under reduced motion) everything still works, instantly.
 */
(function (w, d) {
  "use strict";
  const list = d.getElementById("work-list");
  if (!list || d.body.dataset.page !== "work") return;

  const root = d.documentElement;
  const $ = (s, r = d) => r.querySelector(s);
  const $$ = (s, r = d) => Array.from(r.querySelectorAll(s));
  const FILTERS = ["all", "cafes", "restaurants", "bars", "retail"];
  const ALIASES = { cafe: "cafes", "café": "cafes", "cafés": "cafes", restaurant: "restaurants", bar: "bars", shop: "retail", shops: "retail", store: "retail", stores: "retail" };
  const VIEW_KEY = "ts-work-view";
  const store = {
    get(k) { try { return w.localStorage.getItem(k); } catch (_) { return null; } },
    set(k, v) { try { w.localStorage.setItem(k, v); } catch (_) {} },
  };
  let SEO = {};
  try { SEO = JSON.parse(($("#work-seo") || {}).textContent || "{}"); } catch (_) {}

  const items = $$(".work-item", list);
  const empty = d.getElementById("work-empty");
  const status = d.getElementById("work-status");
  const radios = $$(".work-filter__input");
  const viewBtns = $$(".work-view__btn");
  const layer = list.parentElement;                         // ghosts live here (position: relative)
  const below = () => [$(".work-cta"), $(".site-footer")].filter(Boolean);
  const metaDesc = $('meta[name="description"]');
  const ogTitle = $('meta[property="og:title"]');
  const ogDesc = $('meta[property="og:description"]');

  const matches = (li, f) => f === "all" || li.dataset.filter === f;
  const shown = () => items.filter((li) => !li.classList.contains("is-out"));
  const leadOf = (li, v) => $(v === "grid" ? ".work-item__cover" : ".work-item__lead", li);

  function readURL() {
    let q = "";
    try { q = (new URL(w.location.href).searchParams.get("filter") || "").toLowerCase(); } catch (_) {}
    q = ALIASES[q] || q;
    return FILTERS.includes(q) ? q : "all";
  }
  function writeURL(f) {
    try {
      const u = new URL(w.location.href);
      if (f === "all") u.searchParams.delete("filter"); else u.searchParams.set("filter", f);
      const next = u.pathname + u.search + u.hash;
      if (next !== w.location.pathname + w.location.search + w.location.hash) w.history.replaceState(w.history.state, "", next);
    } catch (_) {}
  }

  let filter = FILTERS.includes(root.dataset.workFilter) ? root.dataset.workFilter : readURL();
  let view = root.dataset.workView === "grid" ? "grid" : "rows";

  /* ---------------------------------------------------------------- sync helpers (no animation) */
  function applyItems() {
    let n = 0;
    items.forEach((li) => { const on = matches(li, filter); li.classList.toggle("is-out", !on); n += on ? 1 : 0; });
    if (empty) empty.classList.toggle("is-shown", n === 0);
    return n;
  }
  function syncControls() {
    radios.forEach((r) => { r.checked = r.value === filter; });
    viewBtns.forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.view === view)));
  }
  function syncSEO() {
    const s = SEO[filter] || SEO.all;
    if (!s) return;
    d.title = s.title;
    metaDesc && metaDesc.setAttribute("content", s.description);
    ogTitle && ogTitle.setAttribute("content", s.title);
    ogDesc && ogDesc.setAttribute("content", s.description);
  }
  // Only one element per page may carry a view-transition-name: the visible layout's lead image.
  function syncVT() {
    items.forEach((li) => {
      const lead = $(".work-item__lead", li), cover = $(".work-item__cover", li), name = "proj-" + li.dataset.slug;
      if (!lead || !cover) return;
      if (view === "grid") { lead.style.viewTransitionName = "none"; cover.style.viewTransitionName = name; }
      else { lead.style.viewTransitionName = name; cover.style.removeProperty("view-transition-name"); }
    });
  }
  function announce(n) {
    if (!status) return;
    const s = SEO[filter];
    status.textContent = (s ? s.label + ": " : "") + (s && s.countText ? s.countText : n + (n === 1 ? " project" : " projects"));
  }

  /* ---------------------------------------------------------------- state changes */
  let fx = null;        // animation layer; installed by Motion.page while motion is allowed
  let loops = null;     // hover-loop controller (grid, fine pointers)

  function setFilter(f, opts = {}) {
    if (!opts.force) { f = ALIASES[f] || f; if (!FILTERS.includes(f)) f = "all"; }
    if (f === filter && !opts.force) { syncControls(); return; }
    const prev = filter;
    const run = fx && opts.animate !== false ? fx.beforeFilter(prev, f) : null;
    filter = f;
    root.dataset.workFilter = f;
    const n = applyItems();
    syncControls();
    syncSEO();
    if (opts.url !== false) writeURL(f);
    if (opts.announce !== false) announce(n);
    loops && loops.refresh();
    run && run();
  }

  function setView(v, opts = {}) {
    v = v === "grid" ? "grid" : "rows";
    if (v === view) { syncControls(); return; }
    loops && loops.stopAll();
    const run = fx && opts.animate !== false ? fx.beforeView(view, v) : null;
    view = v;
    root.dataset.workView = v;
    syncControls();
    syncVT();
    if (opts.save !== false) store.set(VIEW_KEY, v);
    run && run();
  }

  radios.forEach((r) => r.addEventListener("change", () => { if (r.checked) setFilter(r.value); }));
  viewBtns.forEach((b) => b.addEventListener("click", () => setView(b.dataset.view)));
  w.addEventListener("popstate", () => setFilter(readURL(), { url: false }));
  w.addEventListener("pageshow", (e) => {
    if (!e.persisted) return;
    const f = readURL();
    if (f !== filter) setFilter(f, { animate: false, url: false, announce: false });
    syncControls();
  });

  // first sync: the <head> script already set the attributes; make everything agree with them
  root.dataset.workFilter = filter;
  root.dataset.workView = view;
  applyItems(); syncControls(); syncSEO(); syncVT();
  // Projects hidden by a ?filter= load get no scroll reveal (motion.js boots after this file):
  // a display:none trigger measures start = end = 0, fires inside another trigger's refresh
  // and, being `once`, kills itself mid-loop, which makes ScrollTrigger 3.15 throw. They
  // enter through the filter animation instead.
  items.forEach((li) => { if (li.classList.contains("is-out")) $$("[data-reveal]", li).forEach((el) => el.removeAttribute("data-reveal")); });

  const TS = (w.TS = w.TS || {});
  TS.work = { setFilter, setView, get state() { return { filter, view }; } };

  /* ================================================================ motion layer */
  const M = w.Motion;
  if (!M || !M.page) return;

  M.page("work", (env) => {
    const gsap = w.gsap, Flip = w.Flip, SplitText = w.SplitText, ST = w.ScrollTrigger;
    const offs = [];
    if (env.motion && gsap && Flip) {
      gsap.registerPlugin(Flip);
      fx = makeFx(gsap, Flip, SplitText, ST);
      offs.push(() => { fx && fx.kill(); fx = null; });
      introTitle(gsap, SplitText);
    }
    if (env.motion && env.fine && gsap) {
      loops = makeLoops(gsap);
      offs.push(() => { loops && loops.kill(); loops = null; });
    }
    return () => offs.forEach((f) => f());
  });

  /* ---------------------------------------------------------------- masked lines */
  function splitLines(SplitText, el) {
    const s = SplitText.create(el, { type: "lines", mask: "lines", tag: "span", linesClass: "work-line", aria: "none" });
    (s.masks || []).forEach((m) => m.classList.add("work-line-mask"));
    return s;
  }
  const variant = (stack, f) => stack && stack.querySelector(`:scope > .work-swap__v[data-f="${f}"]`);

  let introDone = false;
  function introTitle(gsap, SplitText) {
    const h = $(".work-hero__title");
    if (!h || introDone) { h && gsap.set(h, { opacity: 1 }); return; }
    introDone = true;
    let ran = false;
    const run = () => {
      if (ran) return; ran = true;
      const v = variant(h, filter);
      if (!v || !SplitText) { gsap.set(h, { opacity: 1 }); return; }
      const s = splitLines(SplitText, v);
      gsap.set(h, { opacity: 1 });
      gsap.from(s.lines, {
        yPercent: 140, duration: 1.1, stagger: 0.09, ease: M.DRIFT, delay: (M.introDelay || 0) + 0.05,
        onComplete: () => s.revert(),
      });
    };
    if (d.fonts && d.fonts.status !== "loaded") { d.fonts.ready.then(run); setTimeout(run, 1500); } else run();
  }

  /* ---------------------------------------------------------------- Flip + swaps */
  function makeFx(gsap, Flip, SplitText, ST) {
    let flipTl = null, swapTl = null, viewTl = null, revealsDone = false;
    const ghosts = new Set();

    // Scroll reveals that have not played yet would replay on top of a Flip: finish them first.
    // Once done, the list is plain static content: dropping data-reveal also drops base.css's
    // hidden pre-state, so clearProps on these elements can never hide them again.
    function completeReveals() {
      if (revealsDone || !ST) return;
      revealsDone = true;
      ST.getAll().forEach((st) => {
        if (st.trigger && list.contains(st.trigger) && st.animation) { st.animation.progress(1); st.kill(); }
      });
      $$("[data-reveal]", list).forEach((el) => el.removeAttribute("data-reveal"));
    }
    function finishRunning() {
      [flipTl, viewTl, swapTl].forEach((t) => t && t.progress(1));
      flipTl = viewTl = swapTl = null;
      ghosts.forEach((g) => g.remove()); ghosts.clear();
    }

    // headline / intro: old lines roll up and out, new lines roll up and in (SplitText line masks).
    // The one-line CTA and count roll as a whole inside their clipped stack.
    function prepSwap(prev, next) {
      const pairs = $$(".work-swap").map((s) => ({
        s, out: variant(s, prev), in: variant(s, next), whole: !SplitText || s.dataset.swap === "cta" || s.dataset.swap === "count",
      }));
      pairs.forEach((p) => p.out && p.out.classList.add("is-leaving"));
      return () => {
        const splits = [], moved = [];
        const tl = (swapTl = gsap.timeline({
          onComplete() {
            splits.forEach((s) => s.revert());
            gsap.set(moved, { clearProps: "transform,opacity" });
            pairs.forEach((p) => { p.out && p.out.classList.remove("is-leaving"); p.s.classList.remove("is-swapping"); });
          },
        }));
        const amount = (n, k) => Math.min(k * 4, n * k);
        pairs.forEach((p) => {
          if (p.whole) {
            p.s.classList.add("is-swapping");
            if (p.out) { moved.push(p.out); tl.to(p.out, { yPercent: -110, duration: 0.42, ease: "ts.cut" }, 0); }
            if (p.in) { moved.push(p.in); tl.from(p.in, { yPercent: 110, duration: 0.78, ease: M.DRIFT }, 0.16); }
            return;
          }
          if (p.out) {
            const s = splitLines(SplitText, p.out); splits.push(s);
            tl.to(s.lines, { yPercent: -150, duration: 0.42, ease: "ts.cut", stagger: { amount: amount(s.lines.length, 0.03) } }, 0);
            tl.to(s.lines, { opacity: 0, duration: 0.18, ease: "none", stagger: { amount: amount(s.lines.length, 0.03) } }, 0.2);
          }
          if (p.in) {
            const s = splitLines(SplitText, p.in); splits.push(s);
            tl.from(s.lines, { yPercent: 140, duration: 0.8, ease: M.DRIFT, stagger: { amount: amount(s.lines.length, 0.05) } }, 0.16);
          }
        });
      };
    }

    function beforeFilter(prev, next) {
      completeReveals();
      const targets = [...items, empty, ...below()].filter(Boolean);
      const state = Flip.getState(targets, { props: "opacity" });
      finishRunning();
      const swap = prepSwap(prev, next);
      return () => {
        const grid = view === "grid";
        flipTl = Flip.from(state, {
          targets, duration: 0.9, ease: "ts.inOut", absoluteOnLeave: true, prune: true,
          onEnter: (els) => gsap.fromTo(els,
            { autoAlpha: 0, scale: grid ? 0.9 : 0.985, y: grid ? 28 : 40 },
            { autoAlpha: 1, scale: 1, y: 0, duration: 0.8, delay: 0.26, stagger: 0.07, ease: M.DRIFT, clearProps: "opacity,visibility,transform" }),
          onLeave: (els) => gsap.to(els, { autoAlpha: 0, scale: grid ? 0.9 : 0.985, duration: 0.4, ease: "power2.in", stagger: 0.03 }),
          onComplete: () => { flipTl = null; },
        });
        swap();
      };
    }

    // a clone of a leaving element, pinned where it was, that fades out while the layout changes
    function ghostOut(el, L) {
      const r = el.getBoundingClientRect();
      if (!r.width || r.bottom < -200 || r.top > innerHeight + 200) return null;
      const cs = getComputedStyle(el);
      const c = el.cloneNode(true);
      [c, ...c.querySelectorAll("[data-reveal],[id],[data-reveal-group]")].forEach((n) => {
        n.removeAttribute("data-reveal"); n.removeAttribute("data-reveal-group"); n.removeAttribute("id");
      });
      c.setAttribute("aria-hidden", "true");
      c.classList.add("work-ghost");
      Object.assign(c.style, {
        position: "absolute", left: r.left - L.left + "px", top: r.top - L.top + "px",
        width: r.width + "px", height: r.height + "px", margin: "0", display: cs.display,
        pointerEvents: "none", zIndex: "0", viewTransitionName: "none",
      });
      layer.appendChild(c); ghosts.add(c);
      return c;
    }

    // lead image morph: the new lead starts where the old one was, at the old one's shape
    // (uniform scale + clip-path window, so the photo never stretches), with a ghost of the
    // old photo inside the window that fades as the new one takes over.
    function morph(oldEl, r0, newEl, tl) {
      const r1 = newEl.getBoundingClientRect();
      if (!r0 || !r0.width || !r1.width) return;
      const off = (r) => r.bottom < -100 || r.top > innerHeight + 100;
      if (off(r0) && off(r1)) return;
      const s = Math.max(r0.width / r1.width, r0.height / r1.height);
      const ix = Math.max(0, ((r1.width - r0.width / s) / 2 / r1.width) * 100);
      const iy = Math.max(0, ((r1.height - r0.height / s) / 2 / r1.height) * 100);
      const dx = r0.left + r0.width / 2 - (r1.left + r1.width / 2);
      const dy = r0.top + r0.height / 2 - (r1.top + r1.height / 2);
      const oldImg = oldEl.querySelector("img");
      let ghost = null;
      if (oldImg && oldImg.currentSrc) {
        ghost = d.createElement("img");
        ghost.src = oldImg.currentSrc; ghost.alt = ""; ghost.decoding = "sync";
        ghost.className = "work-ghost-img is-loaded";
        ghost.setAttribute("aria-hidden", "true");
        ghost.style.cssText = `left:${ix}%;top:${iy}%;width:${100 - 2 * ix}%;height:${100 - 2 * iy}%;object-position:${getComputedStyle(oldImg).objectPosition}`;
        newEl.appendChild(ghost); ghosts.add(ghost);
      }
      tl.fromTo(newEl,
        { x: dx, y: dy, scale: s, clipPath: `inset(${iy}% ${ix}% ${iy}% ${ix}%)`, zIndex: 2 },
        { x: 0, y: 0, scale: 1, clipPath: "inset(0% 0% 0% 0%)", duration: 0.95, ease: "ts.cut",
          onComplete: () => { gsap.set(newEl, { clearProps: "transform,zIndex", clipPath: "none" }); if (ghost) { ghost.remove(); ghosts.delete(ghost); } } }, 0);
      if (ghost) tl.to(ghost, { opacity: 0, duration: 0.55, ease: "power1.inOut" }, 0.18);
    }

    function beforeView(prev, next) {
      completeReveals();
      finishRunning();
      const vis = shown();
      const L = layer.getBoundingClientRect();
      const texts = vis.flatMap((li) => $$(".work-item__index, .work-item__name, .work-item__meta", li));
      const olds = new Map(vis.map((li) => { const el = leadOf(li, prev); return [li, { el, r: el && el.getBoundingClientRect() }]; }));
      // leaving in rows → grid: the other row images, the one-liner and the "View project" line
      const leaving = prev === "rows"
        ? vis.flatMap((li) => [...$$(".work-item__img:not(.work-item__lead)", li), $(".work-item__line", li), $(".work-item__cta", li)]).map((el) => ghostOut(el, L)).filter(Boolean)
        : [];
      const state = Flip.getState([...texts, ...below()]);
      return () => {
        const tl = (viewTl = gsap.timeline({ onComplete: () => { viewTl = null; } }));
        tl.add(Flip.from(state, { targets: [...texts, ...below()], duration: 0.95, ease: "ts.cut", scale: true, stagger: 0.012 }), 0);
        vis.forEach((li) => { const o = olds.get(li); const n = leadOf(li, next); if (o && o.el && n) morph(o.el, o.r, n, tl); });
        if (leaving.length) tl.to(leaving, { opacity: 0, duration: 0.3, ease: "power1.out", onComplete: () => leaving.forEach((g) => { g.remove(); ghosts.delete(g); }) }, 0);
        if (next === "rows") {
          const sides = vis.flatMap((li) => $$(".work-item__img:not(.work-item__lead)", li));
          const extra = vis.flatMap((li) => [$(".work-item__line", li), $(".work-item__cta", li)]);
          tl.fromTo(sides, { autoAlpha: 0, x: -28 }, { autoAlpha: 1, x: 0, duration: 0.8, ease: M.DRIFT, stagger: 0.05, clearProps: "opacity,visibility,transform" }, 0.42);
          tl.fromTo(extra, { autoAlpha: 0, y: 14 }, { autoAlpha: 1, y: 0, duration: 0.7, ease: M.DRIFT, stagger: 0.03, clearProps: "opacity,visibility,transform" }, 0.5);
        }
      };
    }

    return {
      beforeFilter, beforeView,
      kill() { finishRunning(); },
    };
  }

  /* ---------------------------------------------------------------- hover loops (grid, fine pointers) */
  function makeLoops(gsap) {
    const cards = items.map((li) => ({ li, v: $(".work-item__loop", li) })).filter((c) => c.v);
    let active = null;
    const show = (c) => {
      if (active !== c) return;
      gsap.to(c.v, { opacity: 1, duration: 0.85, ease: "ts.out", overwrite: "auto" });
      gsap.fromTo(c.v, { scale: 1.06 }, { scale: 1, duration: 1.8, ease: "ts.out", overwrite: false });
    };
    const load = (v) => {
      if (v.dataset.loaded) return;
      v.dataset.loaded = "1";
      if (v.dataset.poster) v.poster = v.dataset.poster;
      v.muted = true; v.playsInline = true;
      v.src = TS.pickVideoSrc ? TS.pickVideoSrc(v) : v.dataset.src + ".mp4";
      v.preload = "auto";
    };
    function enter(c) {
      if (view !== "grid" || c.li.classList.contains("is-out")) return;
      if (active && active !== c) leave(active);
      active = c;
      const v = c.v;
      load(v);
      const ready = () => {
        if (active !== c) return;
        if ("requestVideoFrameCallback" in v) v.requestVideoFrameCallback(() => show(c)); else show(c);
      };
      const p = v.play();
      if (p && p.then) p.then(ready).catch(() => {}); else ready();
    }
    function leave(c) {
      if (active === c) active = null;
      gsap.to(c.v, { opacity: 0, duration: 0.55, ease: "power2.out", overwrite: "auto", onComplete: () => { if (active !== c) c.v.pause(); } });
    }
    const offs = [];
    cards.forEach((c) => {
      const on = (e) => { if (!e.pointerType || e.pointerType === "mouse") enter(c); };
      const off = (e) => { if (!e.pointerType || e.pointerType === "mouse") leave(c); };
      const fin = () => enter(c);
      const fout = (e) => { if (!c.li.contains(e.relatedTarget)) leave(c); };
      c.li.addEventListener("pointerenter", on); c.li.addEventListener("pointerleave", off);
      c.li.addEventListener("focusin", fin); c.li.addEventListener("focusout", fout);
      offs.push(() => { c.li.removeEventListener("pointerenter", on); c.li.removeEventListener("pointerleave", off); c.li.removeEventListener("focusin", fin); c.li.removeEventListener("focusout", fout); });
    });
    // never leave a loop running off screen or in a background tab
    const io = new IntersectionObserver((es) => es.forEach((e) => { if (!e.isIntersecting && active && active.li === e.target) leave(active); }));
    cards.forEach((c) => io.observe(c.li));
    const vis = () => { if (d.hidden && active) leave(active); };
    d.addEventListener("visibilitychange", vis);
    const stopAll = () => { active = null; cards.forEach((c) => { gsap.killTweensOf(c.v); gsap.set(c.v, { opacity: 0, clearProps: "transform" }); c.v.pause(); }); };
    return {
      stopAll,
      refresh() { if (active && active.li.classList.contains("is-out")) leave(active); },
      kill() { stopAll(); io.disconnect(); d.removeEventListener("visibilitychange", vis); offs.forEach((f) => f()); },
    };
  }
})(window, document);
